CREATE TABLE escrow_transactions (
    id SERIAL PRIMARY KEY,
    order_id VARCHAR(64) NOT NULL,
    amount DECIMAL(12,2) NOT NULL,
    status VARCHAR(20) DEFAULT 'PENDING',
    locked_at TIMESTAMP DEFAULT NOW(),
    released_at TIMESTAMP
);

CREATE INDEX idx_escrow_status ON escrow_transactions(status);

export default function EscrowCard({ transaction }) {
  const statusColor = {
    PENDING: 'text-yellow-400',
    RELEASED: 'text-green-400',
    DISPUTED: 'text-red-400'
  };
  return (
    <div className="glass-panel p-4">
      <h3>{transaction.order_id}</h3>
      <span className={statusColor[transaction.status]}>
        {transaction.status}
      </span>
    </div>
  );
}

from collections import defaultdict

class TransactionCategorizer:
    def __init__(self, rules: dict):
        self.rules = rules
        self.cache = defaultdict(list)

    def categorize(self, txn: dict) -> str:
        merchant = txn['merchant'].lower()
        for category, keywords in self.rules.items():
            if any(kw in merchant for kw in keywords):
                self.cache[category].append(txn)
                return category
        return 'UNCATEGORIZED'

import { useMemo } from 'react';
import { PieChart, Pie, Cell } from 'recharts';

export function SpendingDashboard({ transactions }) {
  const breakdown = useMemo(() => {
    return transactions.reduce((acc, txn) => {
      acc[txn.category] = (acc[txn.category] || 0) + txn.amount;
      return acc;
    }, {});
  }, [transactions]);

  return <PieChart width={400} height={400}>...</PieChart>;
}

export function WorkoutLog({ exercises }) {
  return (
    <div className="workout-grid">
      {exercises.map(ex => (
        <div key={ex.id} className="exercise-card">
          <h3>{ex.name}</h3>
          <p>{ex.sets} x {ex.reps} @ {ex.weight}kg</p>
          <meter value={ex.intensity} max={10} />
        </div>
      ))}
    </div>
  );
}

import { Canvas } from '@react-three-fiber';
import { OrbitControls } from '@react-three/drei';

export function LearningScene({ lesson }) {
  return (
    <Canvas camera={{ position: [0, 2, 5] }}>
      <ambientLight intensity={0.5} />
      <OrbitControls enableDamping />
      {lesson.objects.map(obj => (
        <mesh key={obj.id} position={obj.pos}>
          <boxGeometry args={[1,1,1]} />
          <meshStandardMaterial color={obj.color} />
        </mesh>
      ))}
    </Canvas>
  );
}

